/**
 * Server functions for AI-visibility analysis: Share of Voice. Read-only —
 * derived entirely from existing prompt_runs data via the postgres read layer
 * plus the pure stats in `@/lib/visibility-stats`. No schema changes.
 *
 * Filters are resolved server-side (tags/search -> prompt IDs) via
 * `resolveFilteredPrompts`, and the lookback window is computed in the user's
 * timezone — the same handling as the visibility page (see issue #68), so we
 * never serialize a brand's full prompt-id list into the request URL.
 *
 * The Opportunities page is generated by an LLM and lives in `server/opportunities.ts`.
 */
import { createServerFn } from "@tanstack/react-start";
import type { BrandSentiment } from "@/lib/analytics/core";
import {
	brandSentimentInput,
	computeBrandSentiment,
	computeLandscape,
	computeShareOfVoice,
	landscapeInput,
	type ShareOfVoiceResponse,
	shareOfVoiceInput,
} from "@/lib/analytics/pages/analysis";
import { pgReader } from "@/lib/analytics/pg-reader";
import { requireBrandSession } from "@/lib/auth/helpers";
import type { Landscape } from "@/lib/landscape";

export type { ShareOfVoiceEntry, ShareOfVoiceResponse } from "@/lib/analytics/pages/analysis";

export const getShareOfVoiceFn = createServerFn({ method: "GET" })
	.validator(shareOfVoiceInput)
	.handler(async ({ data }): Promise<ShareOfVoiceResponse> => {
		await requireBrandSession(data.brandId);
		return computeShareOfVoice(pgReader, data);
	});

export const getCompetitiveLandscapeFn = createServerFn({ method: "GET" })
	.validator(landscapeInput)
	.handler(async ({ data }): Promise<Landscape> => {
		await requireBrandSession(data.brandId);
		return computeLandscape(pgReader, data);
	});

export const getBrandSentimentFn = createServerFn({ method: "GET" })
	.validator(brandSentimentInput)
	.handler(async ({ data }): Promise<BrandSentiment> => {
		await requireBrandSession(data.brandId);
		return computeBrandSentiment(pgReader, data);
	});
